  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Svatá Hora u Příbrami', 'Nádherný barokní poutní areál s ambity a stříbrným oltářem nad Příbramí, jedno z nejvýznamnějších mariánských poutních míst Čech. Skvost od Dientzenhofera.', 49.6853, 14.0208, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%A1_Hora_P%C5%99%C3%ADbram.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%A1_Hora_P%C5%99%C3%ADbram.jpg"}'::text[], 0),
    (v_route, 'Zámek Dobříš', 'Elegantní rokokový zámek s francouzskou a anglickou zahradou, sídlo Colloredo-Mansfeldů. Zvaný český Versailles.', 49.7794, 14.1706, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Dob%C5%99%C3%AD%C5%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Dob%C5%99%C3%AD%C5%A1.jpg"}'::text[], 1),
    (v_route, 'Brdy – vrch Tok', 'Jedno z nejvyšších míst Brd s vřesovišti v bývalé dopadové ploše, dnes klidná chráněná krajina. Ráj lesních silnic.', 49.71, 13.85, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brdy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brdy.jpg"}'::text[], 2),
    (v_route, 'Hornické muzeum Příbram', 'Největší hornické muzeum v Česku s možností svezení důlním vláčkem. Připomínka stříbrné a uranové minulosti.', 49.6772, 14.0089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hornick%C3%A9_muzeum_P%C5%99%C3%ADbram.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hornick%C3%A9_muzeum_P%C5%99%C3%ADbram.jpg"}'::text[], 3),
    (v_route, 'Zámek Mníšek pod Brdy', 'Barokní zámek s věžemi na okraji Brd, obklopený lesy. Půvabná zastávka na cestě z Prahy.', 49.8683, 14.2622, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Mn%C3%AD%C5%A1ek_pod_Brdy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Mn%C3%AD%C5%A1ek_pod_Brdy.jpg"}'::text[], 4);
