  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Točník', 'Královský gotický hrad Václava IV. na skále nad Žebrákem s dochovaným palácem. Působivá dominanta kraje.', 49.858, 13.882, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_To%C4%8Dn%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_To%C4%8Dn%C3%ADk.jpg"}'::text[], 0),
    (v_route, 'Hrad Žebrák', 'Zřícenina staršího hradu pod Točníkem s válcovou věží, romanticky posazená na ostrohu. Dvojice hradů na dohled.', 49.876, 13.897, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_%C5%BDebr%C3%A1k.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_%C5%BDebr%C3%A1k.jpg"}'::text[], 1),
    (v_route, 'Beroun – medvědárium', 'Historické město s medvědy Vojtou, Kubou a Matějem z večerníčku. Příjemná zastávka na náměstí.', 49.9639, 14.0722, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beroun.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beroun.jpg"}'::text[], 2),
    (v_route, 'Sklárna Nižbor', 'Rukodělná sklárna Rückl s prohlídkou výroby broušeného skla nad Berounkou. Zastávka pro milovníky řemesla.', 49.9944, 14.04, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg"}'::text[], 3),
    (v_route, 'Svatý Jan pod Skalou', 'Malebná obec s klášterem a vápencovou skálou v srdci Českého krasu. Klidné poutní místo v údolí.', 49.9686, 14.135, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%BD_Jan_pod_Skalou.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%BD_Jan_pod_Skalou.jpg"}'::text[], 4);
  insert into public.routes
