  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Slapská přehrada – hráz', 'Mohutná hráz nejznámější vltavské přehrady, oblíbené rekreační jezero středních Čech. Výhled na vodní hladinu i turbíny.', 49.821, 14.427, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slapy_dam.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slapy_dam.jpg"}'::text[], 0),
    (v_route, 'Štěchovice', 'Rekreační městečko u Vltavy s přístavištěm a nedalekou přehradou. Brána do vltavského kaňonu.', 49.85, 14.415, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0t%C4%9Bchovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0t%C4%9Bchovice.jpg"}'::text[], 1),
    (v_route, 'Svatojánské proudy', 'Bývalé divoké peřeje Vltavy, dnes zklidněné přehradou, s romantickými skalami. Malebná scenérie kaňonu.', 49.835, 14.415, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svatoj%C3%A1nsk%C3%A9_proudy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svatoj%C3%A1nsk%C3%A9_proudy.jpg"}'::text[], 2),
    (v_route, 'Vyhlídka Máj (Teletín)', 'Slavná skalní vyhlídka nad meandrem Vltavy s pohledem na zákrut řeky. Jeden z nejfotografovanějších výhledů Čech.', 49.788, 14.415, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vyhl%C3%ADdka_M%C3%A1j.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vyhl%C3%ADdka_M%C3%A1j.jpg"}'::text[], 3),
    (v_route, 'Živohošť', 'Rekreační osada u Slapského jezera s plážemi a kostelem. Zastávka na koupání a klid.', 49.78, 14.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDivoho%C5%A1%C5%A5.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDivoho%C5%A1%C5%A5.jpg"}'::text[], 4);
