  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Velký Blaník', 'Bájná zalesněná hora s rozhlednou na vrcholu, kde podle pověsti čeká blanické vojsko na nejtěžší chvíli národa. Symbolický vrchol Čech.', 49.638, 14.873, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD_Blan%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD_Blan%C3%ADk.jpg"}'::text[], 0),
    (v_route, 'Zámek a park Vlašim', 'Zámek s jedním z nejstarších krajinářských parků v Česku podél řeky Blanice. Příjemná zastávka na procházku.', 49.706, 14.899, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Vla%C5%A1im.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Vla%C5%A1im.jpg"}'::text[], 1),
    (v_route, 'Hrad Český Šternberk', 'Mohutný gotický hrad tyčící se na skalním ostrohu nad Sázavou, v držení rodu Šternberků přes 700 let. Jeden z nejzachovalejších hradů Čech.', 49.808, 14.933, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_%C4%8Cesk%C3%BD_%C5%A0ternberk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_%C4%8Cesk%C3%BD_%C5%A0ternberk.jpg"}'::text[], 2),
    (v_route, 'Louňovice pod Blaníkem', 'Půvabné městečko pod Blaníkem s muzeem a výchozím bodem na horu. Klidná zastávka na úpatí legendy.', 49.628, 14.883, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lou%C5%88ovice_pod_Blan%C3%ADkem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lou%C5%88ovice_pod_Blan%C3%ADkem.jpg"}'::text[], 3),
    (v_route, 'Podblanické muzeum', 'Muzeum přírody a historie kraje ve Vlašimi. Vhodná zastávka i za nepohody.', 49.706, 14.901, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vla%C5%A1im.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vla%C5%A1im.jpg"}'::text[], 4);
