  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Bezděz', 'Majestátní raně gotický královský hrad s dvěma věžemi na vrcholu čedičového kužele, dominanta Máchova kraje. Nezapomenutelné výhledy do kraje.', 50.539, 14.72, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Bezd%C4%9Bz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Bezd%C4%9Bz.jpg"}'::text[], 0),
    (v_route, 'Hrad Houska', 'Tajemný gotický hrad opředený legendami o bráně do pekla. Záhadná zastávka uprostřed lesů Kokořínska.', 50.489, 14.585, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Houska.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Houska.jpg"}'::text[], 1),
    (v_route, 'Máchovo jezero', 'Rozlehlé rybniční jezero u Doks, oblíbené rekreační místo opěvané básníkem Máchou. Pláže a projížďky lodí.', 50.581, 14.64, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A1chovo_jezero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A1chovo_jezero.jpg"}'::text[], 2),
    (v_route, 'Zámek Mělník a soutok', 'Renesanční zámek nad soutokem Labe a Vltavy s vinicemi a proslulým vínem. Výhled na spojení dvou řek.', 50.35, 14.474, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_M%C4%9Bln%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_M%C4%9Bln%C3%ADk.jpg"}'::text[], 3),
    (v_route, 'Pokličky (Kokořínský důl)', 'Bizarní pískovcové skalní útvary ve tvaru hub v srdci Kokořínského dolu. Půvabná zastávka na stezce.', 50.462, 14.56, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pokli%C4%8Dky_Koko%C5%99%C3%ADn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pokli%C4%8Dky_Koko%C5%99%C3%ADn.jpg"}'::text[], 4);
