  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Trosky', 'Ikonická zřícenina se dvěma věžemi Baba a Panna na čedičových sopouchech, symbol Českého ráje. Nejznámější silueta kraje.', 50.514, 15.229, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trosky.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trosky.jpg"}'::text[], 0),
    (v_route, 'Hrubá Skála', 'Zámek na pískovcových skalách nad skalním městem s vyhlídkami. Půvabná zastávka v srdci Českého ráje.', 50.542, 15.196, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrub%C3%A1_Sk%C3%A1la.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrub%C3%A1_Sk%C3%A1la.jpg"}'::text[], 1),
    (v_route, 'Prachovské skály', 'Rozlehlé skalní město s věžemi, roklemi a vyhlídkami u Jičína. Ráj turistů i horolezců.', 50.482, 15.315, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prachovsk%C3%A9_sk%C3%A1ly.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prachovsk%C3%A9_sk%C3%A1ly.jpg"}'::text[], 2),
    (v_route, 'Hrad Kost', 'Výborně zachovalý gotický hrad v údolí Plakánku, jeden z nejmohutnějších v Čechách. Působivá pevnost mezi rybníky.', 50.514, 15.098, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Kost.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Kost.jpg"}'::text[], 3),
    (v_route, 'Hrad Valdštejn', 'Nejstarší hrad Českého ráje na pískovcových skalách s romantickými mosty. Kolébka rodu Valdštejnů.', 50.588, 15.176, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Vald%C5%A1tejn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Vald%C5%A1tejn.jpg"}'::text[], 4);
