  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kostnice v Sedlci', 'Proslulá kaple vyzdobená lidskými kostmi s ohromujícím lustrem, UNESCO památka. Ojedinělý a působivý zážitek.', 49.961, 15.288, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedlec_Ossuary.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sedlec_Ossuary.jpg"}'::text[], 0),
    (v_route, 'Zámek Žleby', 'Romantický novogotický zámek s dochovanými interiéry, sbírkou zbraní a oborou. Pohádková zastávka v Železných horách.', 49.891, 15.489, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_%C5%BDleby.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_%C5%BDleby.jpg"}'::text[], 1),
    (v_route, 'Vlašský dvůr', 'Bývalá královská mincovna a sídlo, kde se razil pražský groš. Srdce stříbrné slávy Kutné Hory.', 49.948, 15.267, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vla%C5%A1sk%C3%BD_dv%C5%AFr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vla%C5%A1sk%C3%BD_dv%C5%AFr.jpg"}'::text[], 2),
    (v_route, 'Kaňk', 'Vrch nad Kutnou Horou s výhledem na město a pozůstatky dolování stříbra. Klidná zastávka nad městem.', 49.972, 15.29, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%88k.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%88k.jpg"}'::text[], 3),
    (v_route, 'Přehrada Pařížov', 'Malebná kamenná přehrada na Doubravě v Železných horách. Osvěžující zastávka v přírodě.', 49.831, 15.556, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pa%C5%99%C3%AD%C5%BEov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pa%C5%99%C3%AD%C5%BEov.jpg"}'::text[], 4);
