  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek a lázně Poděbrady', 'Renesanční zámek na břehu Labe s lázeňskou kolonádou a rodištěm krále Jiřího. Klidná zastávka u řeky.', 50.142, 15.119, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Pod%C4%9Bbrady.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Pod%C4%9Bbrady.jpg"}'::text[], 0),
    (v_route, 'Zámek Loučeň', 'Barokní zámek s rozlehlým parkem plným bludišť a labyrintů. Zábavná zastávka pro celou posádku.', 50.288, 15.017, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Lou%C4%8De%C5%88.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Lou%C4%8De%C5%88.jpg"}'::text[], 1),
    (v_route, 'Skanzen Přerov nad Labem', 'Nejstarší národopisné muzeum v přírodě v Čechách s roubenými staveními Polabí. Cesta do venkovské minulosti.', 50.169, 14.803, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skanzen_P%C5%99erov_nad_Labem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skanzen_P%C5%99erov_nad_Labem.jpg"}'::text[], 2),
    (v_route, 'Nymburk – hradby', 'Historické město s dochovanými cihlovými hradbami na břehu Labe, spjaté s Bohumilem Hrabalem. Příjemná zastávka.', 50.186, 15.041, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nymburk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nymburk.jpg"}'::text[], 3),
    (v_route, 'Lysá nad Labem', 'Barokní zámek se sochařskou výzdobou a rozlehlým parkem. Elegantní zastávka v Polabí.', 50.201, 14.834, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Lys%C3%A1_nad_Labem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Lys%C3%A1_nad_Labem.jpg"}'::text[], 4);
