  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lány – zámek a hrob T. G. Masaryka', 'Prezidentský zámek s parkem a nedalekým lesním hřbitovem, kde odpočívá první prezident. Pietní zastávka v lesích.', 50.124, 13.951, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A1ny.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A1ny.jpg"}'::text[], 0),
    (v_route, 'Rakovník', 'Historické chmelařské město s dvojicí bran a náměstím. Klidná výchozí zastávka kraje.', 50.104, 13.734, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rakovn%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rakovn%C3%ADk.jpg"}'::text[], 1),
    (v_route, 'Zbečno a Hamousův statek', 'Vesnice v údolí Berounky s dochovaným roubeným statkem. Ukázka venkovské architektury Křivoklátska.', 50.033, 13.933, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zbe%C4%8Dno.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zbe%C4%8Dno.jpg"}'::text[], 2),
    (v_route, 'Křivoklátsko – Nezabudické skály', 'Skalnaté stráně nad meandrem Berounky v chráněné krajinné oblasti. Klidná zastávka nad řekou.', 50.01, 13.895, 'https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg"}'::text[], 3),
    (v_route, 'Krušovice – pivovar', 'Tradiční pivovar v srdci Rakovnicka s dlouhou historií vaření piva. Zastávka pro spolujezdce.', 50.171, 13.862, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kru%C5%A1ovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kru%C5%A1ovice.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Keltské oppidum Nižbor', 'Keltské informační centrum na místě dávného osídlení nad Berounkou. Cesta ke kořenům české historie.', 49.9944, 14.043, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg"}'::text[], 0),
    (v_route, 'Skryjská jezírka', 'Romantická jezírka s vodopádem v hlubokých lesích Křivoklátska, proslulá nálezy trilobitů. Idylická zastávka v přírodě.', 49.945, 13.752, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skryjsk%C3%A1_jez%C3%ADrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skryjsk%C3%A1_jez%C3%ADrka.jpg"}'::text[], 1),
    (v_route, 'Roztoky u Křivoklátu', 'Vesnice v údolí Berounky pod křivoklátskými lesy s železniční zastávkou. Výchozí bod do divočiny.', 50.047, 13.872, 'https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg"}'::text[], 2),
    (v_route, 'Zbiroh – zámek', 'Zámek na skále, kde Alfons Mucha maloval Slovanskou epopej. Historická zastávka na okraji kraje.', 49.858, 13.768, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Zbiroh.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Zbiroh.jpg"}'::text[], 3),
    (v_route, 'Čertova skála u Berounky', 'Skalní útvar nad meandrem řeky s výhledem do křivoklátských lesů. Klidná vyhlídka na stezce.', 49.96, 13.87, 'https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg"}'::text[], 4);
