-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — STŘEDNÍ ČECHY (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Brdy a Příbramsko
  delete from public.routes where name = 'Brdy a Příbramsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Brdy a Příbramsko', 'Okruh nově otevřenou chráněnou krajinnou oblastí Brdy a okolím Příbrami. Lesní silnice bývalého vojenského prostoru, poutní Svatá Hora a zámek Dobříš spojují klid, historii a svěží vzduch nedaleko Prahy. Nejlepší od jara do podzimu; pozor na lesní úseky a zvěř.', 'loop', 150, 210, 'medium',
     '[{"lat": 49.6853, "lng": 14.01, "label": "Start: Příbram"}, {"lat": 49.71, "lng": 13.85, "label": "Brdy – Tok"}, {"lat": 49.7794, "lng": 14.1706, "label": "Dobříš"}, {"lat": 49.6853, "lng": 14.01, "label": "Cíl: Příbram"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.6853,14.01&destination=49.6853,14.01&travelmode=driving&waypoints=49.71,13.85%7C49.7794,14.1706', 'https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%A1_Hora_P%C5%99%C3%ADbram.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%A1_Hora_P%C5%99%C3%ADbram.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Dob%C5%99%C3%AD%C5%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brdy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hornick%C3%A9_muzeum_P%C5%99%C3%ADbram.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Mn%C3%AD%C5%A1ek_pod_Brdy.jpg"}'::text[], '{"Svatá Hora u Příbrami","Zámek Dobříš","Brdy – vrch Tok","Hornické muzeum Příbram","Zámek Mníšek pod Brdy"}'::text[], '{"CZ"}'::text[], false, 2210, 'approved');

  -- Berounsko a hrady Točník a Žebrák
  delete from public.routes where name = 'Berounsko a hrady Točník a Žebrák' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Berounsko a hrady Točník a Žebrák', 'Okruh Českým krasem a Podbrdskem kolem dvojice hradů nad Žebrákem. Skalnaté údolí Berounky, sklářský Nižbor a medvědi v Berouně nabízí historii i příjemnou jízdu nedaleko Prahy. Nejlepší od jara do podzimu; pozor na turisty u hradů.', 'loop', 130, 180, 'easy',
     '[{"lat": 49.9639, "lng": 14.0722, "label": "Start: Beroun"}, {"lat": 49.876, "lng": 13.897, "label": "Žebrák"}, {"lat": 49.858, "lng": 13.882, "label": "Točník"}, {"lat": 49.9639, "lng": 14.0722, "label": "Cíl: Beroun"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.9639,14.0722&destination=49.9639,14.0722&travelmode=driving&waypoints=49.876,13.897%7C49.858,13.882', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_To%C4%8Dn%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_To%C4%8Dn%C3%ADk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_%C5%BDebr%C3%A1k.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beroun.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Svat%C3%BD_Jan_pod_Skalou.jpg"}'::text[], '{"Hrad Točník","Hrad Žebrák","Beroun – medvědárium","Sklárna Nižbor","Svatý Jan pod Skalou"}'::text[], '{"CZ"}'::text[], false, 2220, 'approved');

  -- Slapy a Svatojánské proudy
  delete from public.routes where name = 'Slapy a Svatojánské proudy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slapy a Svatojánské proudy', 'Trasa údolím Vltavy jižně od Prahy podél kaskády přehrad. Hráz Slapské přehrady, rekreační Štěchovice a skalnaté meandry nabízí vodu, výhledy a klikaté silnice nad řekou. Nejlepší od jara do podzimu; pozor na víkendový provoz u vody.', 'poi', 120, 165, 'easy',
     '[{"lat": 49.85, "lng": 14.415, "label": "Start: Štěchovice"}, {"lat": 49.821, "lng": 14.427, "label": "Slapská přehrada – hráz"}, {"lat": 49.78, "lng": 14.4, "label": "Živohošť"}, {"lat": 49.85, "lng": 14.415, "label": "Cíl: Štěchovice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.85,14.415&destination=49.85,14.415&travelmode=driving&waypoints=49.821,14.427%7C49.78,14.4', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slapy_dam.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slapy_dam.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0t%C4%9Bchovice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Svatoj%C3%A1nsk%C3%A9_proudy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vyhl%C3%ADdka_M%C3%A1j.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDivoho%C5%A1%C5%A5.jpg"}'::text[], '{"Slapská přehrada – hráz","Štěchovice","Svatojánské proudy","Vyhlídka Máj (Teletín)","Živohošť"}'::text[], '{"CZ"}'::text[], false, 2230, 'approved');

  -- Podblanicko a hora Blaník
  delete from public.routes where name = 'Podblanicko a hora Blaník' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Podblanicko a hora Blaník', 'Okruh idylickým Podblanickem kolem bájné hory Blaník, kde podle pověsti spí vojsko svatého Václava. Zámek ve Vlašimi, klidné silnice a lesy nabízí pohodovou jízdu opředenou legendou. Nejlepší od jara do podzimu; pozor na zvěř na okresních silnicích.', 'loop', 140, 180, 'easy',
     '[{"lat": 49.706, "lng": 14.899, "label": "Start: Vlašim"}, {"lat": 49.638, "lng": 14.873, "label": "Velký Blaník"}, {"lat": 49.808, "lng": 14.933, "label": "Český Šternberk"}, {"lat": 49.706, "lng": 14.899, "label": "Cíl: Vlašim"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.706,14.899&destination=49.706,14.899&travelmode=driving&waypoints=49.638,14.873%7C49.808,14.933', 'https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD_Blan%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD_Blan%C3%ADk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Vla%C5%A1im.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_%C4%8Cesk%C3%BD_%C5%A0ternberk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lou%C5%88ovice_pod_Blan%C3%ADkem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vla%C5%A1im.jpg"}'::text[], '{"Velký Blaník","Zámek a park Vlašim","Hrad Český Šternberk","Louňovice pod Blaníkem","Podblanické muzeum"}'::text[], '{"CZ"}'::text[], false, 2240, 'approved');

  -- Kokořínsko, Bezděz a Máchův kraj
  delete from public.routes where name = 'Kokořínsko, Bezděz a Máchův kraj' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kokořínsko, Bezděz a Máchův kraj', 'Trasa pískovcovým Kokořínskem a Máchovým krajem plným skal, hradů a rybníků. Dvojvěží hradu Bezděz, tajemná Houska a Máchovo jezero nabízí romantickou přírodu severně od Prahy. Nejlepší od jara do podzimu; pozor na úzké lesní silnice.', 'poi', 160, 210, 'easy',
     '[{"lat": 50.427, "lng": 14.568, "label": "Start: Mělník"}, {"lat": 50.489, "lng": 14.585, "label": "Houska"}, {"lat": 50.539, "lng": 14.72, "label": "Bezděz"}, {"lat": 50.581, "lng": 14.64, "label": "Máchovo jezero"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.427,14.568&destination=50.581,14.64&travelmode=driving&waypoints=50.489,14.585%7C50.539,14.72', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Bezd%C4%9Bz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Bezd%C4%9Bz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Houska.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%A1chovo_jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_M%C4%9Bln%C3%ADk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pokli%C4%8Dky_Koko%C5%99%C3%ADn.jpg"}'::text[], '{"Hrad Bezděz","Hrad Houska","Máchovo jezero","Zámek Mělník a soutok","Pokličky (Kokořínský důl)"}'::text[], '{"CZ"}'::text[], false, 2250, 'approved');

  -- Český ráj – skály a hrady
  delete from public.routes where name = 'Český ráj – skály a hrady' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Český ráj – skály a hrady', 'Okruh geoparkem Český ráj plným skalních měst a hradů na severu středních Čech. Zřícenina Trosky, Hrubá Skála a Prachovské skály nabízí dramatickou pískovcovou scenérii a klikaté silnice. Nejlepší od jara do podzimu; pozor na turisty a úzké silnice.', 'loop', 150, 210, 'medium',
     '[{"lat": 50.587, "lng": 15.16, "label": "Start: Turnov"}, {"lat": 50.514, "lng": 15.229, "label": "Trosky"}, {"lat": 50.482, "lng": 15.315, "label": "Prachovské skály"}, {"lat": 50.587, "lng": 15.16, "label": "Cíl: Turnov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.587,15.16&destination=50.587,15.16&travelmode=driving&waypoints=50.514,15.229%7C50.482,15.315', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trosky.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trosky.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrub%C3%A1_Sk%C3%A1la.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prachovsk%C3%A9_sk%C3%A1ly.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Kost.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Vald%C5%A1tejn.jpg"}'::text[], '{"Hrad Trosky","Hrubá Skála","Prachovské skály","Hrad Kost","Hrad Valdštejn"}'::text[], '{"CZ"}'::text[], false, 2260, 'approved');

  -- Kutnohorsko a Železné hory
  delete from public.routes where name = 'Kutnohorsko a Železné hory' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kutnohorsko a Železné hory', 'Okruh stříbrnou Kutnou Horou a zvlněnými Železnými horami. Kostnice v Sedlci, romantický zámek Žleby a klidné silnice nabízí historii i pohodovou jízdu východně od Prahy. Nejlepší od jara do podzimu; pozor na turisty v Kutné Hoře.', 'loop', 140, 180, 'easy',
     '[{"lat": 49.961, "lng": 15.288, "label": "Start: Kutná Hora – Sedlec"}, {"lat": 49.891, "lng": 15.489, "label": "Žleby"}, {"lat": 49.82, "lng": 15.56, "label": "Železné hory"}, {"lat": 49.961, "lng": 15.288, "label": "Cíl: Kutná Hora"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.961,15.288&destination=49.961,15.288&travelmode=driving&waypoints=49.891,15.489%7C49.82,15.56', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedlec_Ossuary.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sedlec_Ossuary.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_%C5%BDleby.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vla%C5%A1sk%C3%BD_dv%C5%AFr.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%88k.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pa%C5%99%C3%AD%C5%BEov.jpg"}'::text[], '{"Kostnice v Sedlci","Zámek Žleby","Vlašský dvůr","Kaňk","Přehrada Pařížov"}'::text[], '{"CZ"}'::text[], false, 2270, 'approved');

  -- Polabí a jeho zámky
  delete from public.routes where name = 'Polabí a jeho zámky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Polabí a jeho zámky', 'Trasa rovinatým Polabím východně od Prahy plným zámků a lázní. Lázeňské Poděbrady, romantický Loučeň a skanzen v Přerově nad Labem nabízí pohodovou jízdu a historii u řeky Labe. Nejlepší od jara do podzimu; pozor na provoz ve městech.', 'poi', 150, 180, 'easy',
     '[{"lat": 50.142, "lng": 15.119, "label": "Start: Poděbrady"}, {"lat": 50.288, "lng": 15.017, "label": "Loučeň"}, {"lat": 50.169, "lng": 14.803, "label": "Přerov nad Labem"}, {"lat": 50.142, "lng": 15.119, "label": "Cíl: Poděbrady"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.142,15.119&destination=50.142,15.119&travelmode=driving&waypoints=50.288,15.017%7C50.169,14.803', 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Pod%C4%9Bbrady.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Pod%C4%9Bbrady.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Lou%C4%8De%C5%88.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skanzen_P%C5%99erov_nad_Labem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nymburk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Lys%C3%A1_nad_Labem.jpg"}'::text[], '{"Zámek a lázně Poděbrady","Zámek Loučeň","Skanzen Přerov nad Labem","Nymburk – hradby","Lysá nad Labem"}'::text[], '{"CZ"}'::text[], false, 2280, 'approved');

  -- Rakovnicko a Lánsko
  delete from public.routes where name = 'Rakovnicko a Lánsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rakovnicko a Lánsko', 'Okruh lesnatým Rakovnickem a Křivoklátskem na západě středních Čech. Prezidentské Lány, údolí Berounky a chmelařský Rakovník nabízí klidnou jízdu zelenými lesy. Nejlepší od jara do podzimu; pozor na zvěř na lesních silnicích.', 'loop', 130, 180, 'easy',
     '[{"lat": 50.104, "lng": 13.734, "label": "Start: Rakovník"}, {"lat": 50.124, "lng": 13.951, "label": "Lány"}, {"lat": 50.033, "lng": 13.933, "label": "Zbečno"}, {"lat": 50.104, "lng": 13.734, "label": "Cíl: Rakovník"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.104,13.734&destination=50.104,13.734&travelmode=driving&waypoints=50.124,13.951%7C50.033,13.933', 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A1ny.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A1ny.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rakovn%C3%ADk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zbe%C4%8Dno.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kru%C5%A1ovice.jpg"}'::text[], '{"Lány – zámek a hrob T. G. Masaryka","Rakovník","Zbečno a Hamousův statek","Křivoklátsko – Nezabudické skály","Krušovice – pivovar"}'::text[], '{"CZ"}'::text[], false, 2290, 'approved');

  -- Křivoklátské lesy a Nižbor
  delete from public.routes where name = 'Křivoklátské lesy a Nižbor' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Křivoklátské lesy a Nižbor', 'Okruh hlubokými lesy chráněné krajinné oblasti Křivoklátsko podél řeky Berounky. Skryjská jezírka s trilobity, keltský Nižbor a klikaté lesní silnice nabízí přírodu a klid nedaleko Prahy. Nejlepší od jara do podzimu; pozor na úzké lesní silnice a zvěř.', 'loop', 140, 180, 'medium',
     '[{"lat": 49.9944, "lng": 14.043, "label": "Start: Nižbor"}, {"lat": 49.945, "lng": 13.752, "label": "Skryje"}, {"lat": 50.047, "lng": 13.872, "label": "Roztoky u Křivoklátu"}, {"lat": 49.9944, "lng": 14.043, "label": "Cíl: Nižbor"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.9944,14.043&destination=49.9944,14.043&travelmode=driving&waypoints=49.945,13.752%7C50.047,13.872', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%BEbor.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skryjsk%C3%A1_jez%C3%ADrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Zbiroh.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Berounka.jpg"}'::text[], '{"Keltské oppidum Nižbor","Skryjská jezírka","Roztoky u Křivoklátu","Zbiroh – zámek","Čertova skála u Berounky"}'::text[], '{"CZ"}'::text[], false, 2300, 'approved');

end $$;
